UPDATE products AS p
SET description = v.description
FROM (VALUES
  ('anti-jamur-lumut', 'Cairan pembersih jamur dan lumut untuk permukaan yang lembap seperti dinding kamar mandi, nat keramik, dan tembok luar. Semprotkan pada area yang berjamur, diamkan sebentar, lalu sikat dan bilas. Isi 250 ml, cukup untuk beberapa kali pemakaian di satu kamar mandi.'),
  ('bye-bye-cat-spray-80ml', 'Spray pengusir kucing untuk teras, jok motor, dan sudut yang sering didatangi kucing. Semprotkan sampai permukaannya basah, lalu ulangi ketika aromanya mulai hilang. Jangan disemprotkan langsung ke kucing. Ukuran 80 ml mudah dibawa dan cocok untuk satu area kecil.'),
  ('bye-bye-cicak-gel-50gr', 'Gel pengusir cicak untuk sudut plafon, belakang lemari, dan sekitar lampu tempat cicak berkumpul. Bekerja dengan aroma yang dihindari cicak, bukan racun, jadi tidak ada bangkai yang harus dibersihkan. Ukuran 50 g pas untuk satu ruangan.'),
  ('bye-bye-cicak-spray-220ml', 'Spray pengusir cicak ukuran besar untuk rumah dengan banyak titik cicak. Semprotkan pada dinding, sekitar lampu, dan celah yang sering dilewati cicak, lalu ulangi saat aromanya memudar. Isi 220 ml, sekitar tiga kali lipat botol 80 ml.'),
  ('bye-bye-dog-bad-behavior-gel-80g', 'Gel untuk melatih anjing menjauhi area tertentu, misalnya sofa, kamar, atau sudut yang sering dijadikan tempat buang kotoran. Tebarkan di tempat yang ingin dihindari sampai aromanya tercium. Gel mengering dalam tiga sampai lima hari tergantung cuaca, lalu bisa ditebar ulang.'),
  ('bye-bye-kecoa-spray-80ml', 'Spray pengusir kecoa untuk dapur, bawah wastafel, dan celah lemari. Bekerja dengan aroma yang dihindari kecoa, bukan racun, jadi tidak meninggalkan bangkai yang harus dibersihkan. Ukuran 80 ml praktis disimpan di dapur dan dipakai sewaktu-waktu.'),
  ('bye-bye-lalat-gel-50g', 'Gel pengusir lalat untuk sekitar tempat sampah, dapur, dan area makan di luar ruangan. Cukup diletakkan di titik yang sering dikerubungi lalat. Ukuran 50 g cocok untuk satu titik seperti area tempat sampah.'),
  ('bye-bye-mouse-gel-ekonomis', 'Gel pengusir tikus ukuran hemat untuk satu titik seperti dapur atau gudang kecil. Bersihkan dulu bekas kotoran tikus, lalu sebarkan gel dengan jarak lima sampai sepuluh sentimeter. Bekerja dengan aroma yang dihindari tikus, bukan racun.'),
  ('bye-bye-mouse-spray-220ml', 'Spray pengusir tikus ukuran besar untuk plafon, gudang, dan jalur tikus yang panjang. Paling baik disemprotkan menjelang malam saat tikus mulai aktif. Isi 220 ml untuk rumah dengan banyak titik yang perlu ditangani.'),
  ('bye-bye-semut-spray-80ml', 'Spray pengusir semut untuk jalur semut di lemari makanan, meja dapur, dan sekitar wastafel. Semprotkan pada jalur yang dilewati semut, lalu ulangi ketika aromanya mulai hilang. Ukuran 80 ml praktis disimpan di dapur.'),
  ('bye-bye-snake-gel-50g', 'Gel pengusir ular untuk sekitar pagar, kebun, selokan, dan lubang yang berpotensi jadi jalan masuk ular. Sebarkan di sepanjang batas yang ingin dijaga. Ukuran 50 g cocok untuk satu sisi halaman atau satu titik rawan.'),
  ('bye-bye-snake-gel-80g', 'Gel pengusir ular ukuran 80 g untuk halaman yang lebih luas atau beberapa titik sekaligus. Sebarkan di sepanjang pagar, tepi kebun, dan mulut selokan. Aromanya yang membuat ular menjauh, bukan racun.'),
  ('bye-bye-snake-spray-80ml', 'Spray pengusir ular untuk permukaan yang sulit ditaburi gel, seperti dinding selokan, tumpukan batu, dan celah pagar. Semprotkan pada area tersebut dan ulangi saat aromanya memudar. Ukuran 80 ml untuk pemakaian di beberapa titik.'),
  ('cicago-spray-100ml', 'Spray pengusir cicak untuk dinding, sekitar lampu, dan permukaan yang sering dilewati cicak. Kocok dulu sebelum dipakai, lalu semprotkan secukupnya pada area tersebut. Isi 100 ml untuk pemakaian rutin di beberapa ruangan.'),
  ('gel-pengusir-musang-50g', 'Gel pengusir musang untuk plafon, atap, dan jalur yang sering dilewati musang pada malam hari. Tebarkan sampai aromanya tercium di area tersebut. Gel mengering dalam tiga sampai lima hari tergantung cuaca, lalu bisa ditebar ulang.'),
  ('gocat-gel-jumbo', 'Gel pengusir kucing ukuran jumbo untuk area luas seperti sepanjang pagar, halaman rumah makan, atau plafon. Sebarkan di titik yang sering didatangi kucing. Gel mengering setelah dua sampai tiga hari, lalu disebar ulang saat kucing mulai kembali.'),
  ('gocat-spray-220ml', 'Spray pengusir kucing ukuran besar untuk teras, garasi, dan halaman yang luas. Semprotkan sampai permukaan basah pada titik yang sering didatangi kucing, lalu ulangi saat aromanya hilang. Jangan disemprotkan langsung ke kucing. Isi 220 ml untuk pemakaian jangka panjang.'),
  ('gocat-spray-250ml', 'Spray pengusir kucing isi 250 ml untuk pemakaian rutin di area luas. Putar pengaman di bagian tengah ke kiri agar spray bisa disemprotkan, lalu semprotkan secukupnya di tempat yang ingin dijauhi kucing. Ukuran ini paling hemat untuk pemakaian harian.'),
  ('gocat-spray-80ml', 'Spray pengusir kucing ukuran 80 ml untuk satu area seperti teras atau jok motor. Putar pengaman di bagian tengah ke kiri sebelum menyemprot, lalu semprotkan secukupnya. Ukurannya kecil sehingga mudah dibawa dan disimpan.'),
  ('goito-spray-nyamuk-100ml', 'Spray pengusir nyamuk tanpa asap dan tanpa bakar. Kocok dulu, lalu semprotkan pada ruangan atau permukaan yang sering dilewati nyamuk. Tutup ruangan sekitar lima belas menit setelah disemprot agar aromanya merata. Isi 100 ml.'),
  ('gomouse-gel-70g', 'Gel pengusir tikus dalam kemasan zip yang bisa ditutup kembali. Ambil empat sampai lima butir dan sebarkan di titik yang sering dilewati tikus, lalu tutup kemasannya untuk pemakaian berikutnya. Isi 70 g.'),
  ('gomouse-spray-100ml', 'Spray pengusir tikus untuk plafon, gudang, dan celah yang sering dilewati tikus. Kocok dulu sebelum dipakai, lalu semprotkan pada permukaan tersebut. Isi 100 ml untuk pemakaian rutin.'),
  ('mitigo-spray-rayap', 'Spray pengusir rayap untuk kusen, perabot kayu, dan barang yang rawan didatangi rayap. Kocok dulu, lalu semprotkan pada permukaan kayu yang ingin dilindungi. Isi 100 ml.'),
  ('ogoant-gel-70g', 'Gel pengusir semut dalam kemasan zip yang bisa ditutup kembali. Ambil empat sampai lima butir dan sebarkan di jalur semut, misalnya lemari makanan atau meja dapur. Isi 70 g.'),
  ('ogoant-spray-100ml', 'Spray pengusir semut untuk jalur semut di dapur dan lemari makanan. Kocok dulu, lalu semprotkan pada ruangan atau permukaan yang sering dilewati semut. Tutup ruangan sekitar lima belas menit agar aromanya merata. Isi 100 ml.'),
  ('paket-bye-bye-kecoa-gel-spray', 'Paket pengusir kecoa berisi gel 80 g dan spray 80 ml. Gel untuk celah dan sudut yang jarang disentuh, spray untuk permukaan terbuka seperti meja dapur dan bawah wastafel. Keduanya bekerja dengan aroma yang dihindari kecoa, bukan racun.'),
  ('paket-bye-bye-ular-gel-spray', 'Paket pengusir ular berisi gel 80 g dan spray 80 ml. Gel ditebar di sepanjang pagar dan tepi kebun, spray dipakai untuk dinding selokan dan celah yang sulit ditaburi. Cocok untuk rumah yang berbatasan dengan kebun atau saluran air.'),
  ('paket-cicago-gel-spray', 'Paket pengusir cicak berisi gel 70 g dan spray 100 ml. Gel diletakkan di sudut plafon dan belakang lemari, spray untuk dinding dan sekitar lampu. Dua bentuk ini saling melengkapi untuk menangani satu rumah sekaligus.'),
  ('paket-gocat-gel-spray', 'Paket pengusir kucing berisi gel 70 g dan spray 100 ml. Gel untuk ditebar di halaman dan sepanjang pagar, spray untuk teras, jok motor, dan permukaan yang tidak bisa ditaburi gel. Lebih hemat dibanding membeli terpisah.'),
  ('paket-goito-gel-spray', 'Paket pengusir nyamuk berisi gel 70 g dan spray 100 ml. Gel digantung di dekat kipas atau AC agar aromanya terbawa aliran udara, spray dipakai saat butuh cepat di ruangan tertentu. Keduanya tanpa asap dan tanpa bakar.'),
  ('paket-gomouse-gel-spray', 'Paket pengusir tikus berisi gel 70 g dan spray 100 ml. Gel ditebar di jalur tikus dan sudut gudang, spray untuk plafon dan celah yang sulit dijangkau. Bersihkan dulu bekas kotoran tikus sebelum dipakai.'),
  ('paket-hemat-3-gocat-spray', 'Paket berisi tiga botol GoCat Spray pengusir kucing. Cocok untuk rumah dengan beberapa titik yang perlu ditangani sekaligus, atau untuk stok pemakaian jangka panjang. Harga per botol lebih murah dibanding membeli satuan.'),
  ('paket-ogoant-gel-spray', 'Paket pengusir semut berisi spray 100 ml dan gel 70 g. Gel ditebar di jalur semut dalam lemari, spray dipakai untuk meja dapur dan permukaan terbuka. Lebih hemat dibanding membeli terpisah.'),
  ('sangreat-car-seat-cleaner', 'Pembersih sekaligus pengkilap untuk sofa kulit dan jok mobil. Kocok dulu, semprotkan pada bagian yang ingin dibersihkan, lalu usap merata dengan kain bersih dan lembut sampai permukaannya halus. Pakai secara berkala agar warnanya tidak cepat kusam.'),
  ('sangreat-leather-shoe-cleaner', 'Pembersih sekaligus pengkilap untuk sepatu kulit. Kocok dulu, semprotkan pada bagian yang ingin dibersihkan, lalu usap merata dengan kain lembut sampai permukaannya halus. Keringkan dengan diangin-anginkan, jangan dijemur langsung di bawah matahari. Isi 80 ml.'),
  ('spray-pengusir-musang-80ml', 'Spray pengusir musang untuk plafon, atap, dan jalur yang sering dilewati musang. Kocok dulu, lalu semprotkan secukupnya di area tersebut. Semprot ulang ketika aromanya mulai hilang. Isi 80 ml.')
) AS v (slug, description)
WHERE p.slug = v.slug;
